namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Bio { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public Department Department { get; set; } = null!;
    public Instructor Instructor { get; set; } = null!;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{2}\d{6}$", ErrorMessage = "Student ID must be 2 uppercase letters followed by 6 digits (e.g., CS123456).")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and fundamental forces." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and civilizations." },
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor", Bio = "Dr. Chen specializes in algorithms and distributed systems. She has published over 50 papers and received the ACM Distinguished Educator Award.", Email = "achen@university.edu" },
            new() { Id = 2, Name = "Dr. Robert Martinez", Title = "Associate Professor", Bio = "Dr. Martinez researches machine learning and artificial intelligence with a focus on natural language processing.", Email = "rmartinez@university.edu" },
            new() { Id = 3, Name = "Dr. Sarah Thompson", Title = "Professor", Bio = "Dr. Thompson is a number theorist with 20 years of teaching experience and author of three textbooks.", Email = "sthompson@university.edu" },
            new() { Id = 4, Name = "Dr. James Wilson", Title = "Assistant Professor", Bio = "Dr. Wilson studies quantum mechanics and particle physics. He previously worked at CERN.", Email = "jwilson@university.edu" },
            new() { Id = 5, Name = "Dr. Emily Brooks", Title = "Professor", Bio = "Dr. Brooks is a Shakespeare scholar and creative writing mentor with multiple published novels.", Email = "ebrooks@university.edu" },
            new() { Id = 6, Name = "Dr. Michael Park", Title = "Associate Professor", Bio = "Dr. Park specializes in modern American history and civil rights movements.", Email = "mpark@university.edu" },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, Instructor = _instructors[0], Department = _departments[0], IsFeatured = true },
            new() { Id = 2, Code = "CS 301", Title = "Data Structures & Algorithms", Description = "Advanced study of data structures including trees, graphs, and hash tables. Analysis of algorithm complexity and design patterns.", Credits = 4, Schedule = "Tue/Thu 10:00–11:20 AM", DepartmentId = 1, Instructor = _instructors[0], Department = _departments[0], IsFeatured = true },
            new() { Id = 3, Code = "CS 420", Title = "Machine Learning", Description = "Introduction to machine learning techniques including supervised and unsupervised learning, neural networks, and model evaluation.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", DepartmentId = 1, Instructor = _instructors[1], Department = _departments[0], IsFeatured = true },
            new() { Id = 4, Code = "MATH 201", Title = "Linear Algebra", Description = "Study of vector spaces, linear transformations, matrices, determinants, and eigenvalues with applications.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = 2, Instructor = _instructors[2], Department = _departments[1] },
            new() { Id = 5, Code = "MATH 301", Title = "Abstract Algebra", Description = "Introduction to groups, rings, and fields. Explores the algebraic structures underlying modern mathematics.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", DepartmentId = 2, Instructor = _instructors[2], Department = _departments[1] },
            new() { Id = 6, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM + Lab Thu 2:00–4:00 PM", DepartmentId = 3, Instructor = _instructors[3], Department = _departments[2] },
            new() { Id = 7, Code = "PHYS 310", Title = "Quantum Mechanics", Description = "Introduction to quantum theory: wave functions, Schrödinger equation, angular momentum, and hydrogen atom.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", DepartmentId = 3, Instructor = _instructors[3], Department = _departments[2], IsFeatured = true },
            new() { Id = 8, Code = "ENG 201", Title = "Creative Writing", Description = "Workshop-based course covering fiction, poetry, and creative nonfiction. Students produce a portfolio of original work.", Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", DepartmentId = 4, Instructor = _instructors[4], Department = _departments[3] },
            new() { Id = 9, Code = "ENG 310", Title = "Shakespeare", Description = "Close reading and analysis of Shakespeare's major plays and sonnets in their historical and cultural context.", Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", DepartmentId = 4, Instructor = _instructors[4], Department = _departments[3] },
            new() { Id = 10, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, empires, and cultural developments from antiquity through the late medieval period.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", DepartmentId = 5, Instructor = _instructors[5], Department = _departments[4] },
            new() { Id = 11, Code = "HIST 320", Title = "Civil Rights Movement", Description = "In-depth study of the American civil rights movement from Reconstruction through the present day.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", DepartmentId = 5, Instructor = _instructors[5], Department = _departments[4] },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();
}

